export interface DataTableProps<T> {
    data: T[];
    columns: ColumnDef<T, any>[];
    getRowId?: (row: T, index: number) => string;
    getSubRows?: (row: T) => T[] | undefined;
    selection?: boolean;
    searchable?: boolean;
    toolbar?: React.ReactNode;
    pagination?: boolean;
    pageSize?: number;
    virtual?: boolean;
    virtualColumns?: boolean;
    height?: number;
    loading?: boolean;
    error?: string;
    onRetry?: () => void;
    className?: string;
    density?: 'comfortable' | 'compact';
    onDataChange?: (rows: T[]) => void;
    onCellEdit?: (row: T, columnId: string, value: unknown) => void;
    onSelectionChange?: (rows: T[]) => void;
    rowExpansion?: (row: T) => React.ReactNode;
    getCellProps?: (row: T, columnId: string, index: number) => Partial<CellSpan> | undefined;
    tableOptions?: Partial<Omit<TableOptions<T>, 'data' | 'columns' | 'getCoreRowModel'>>;
    exportName?: string;
    caption?: string;
    storageKey?: string;
    reorderable?: boolean;
    onRowOrderChange?: (rows: T[]) => void;
    summary?: (rows: T[]) => React.ReactNode;
}

export interface EditableColumnMeta {
    editable?: boolean;
    inputType?: 'text' | 'number' | 'date' | 'email';
    validate?: (value: unknown) => string | undefined;
}

export function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }): React.JSX.Element

export interface InputProps extends Omit<React.ComponentProps<'input'>, 'prefix'> {
    leading?: React.ReactNode;
    trailing?: React.ReactNode;
    allowClear?: boolean;
    showCount?: boolean;
    passwordToggle?: boolean;
    onValueChange?: (value: string) => void;
}

export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}): readonly [T, (next: T | ((previous: T) => T)) => void]

export function CheckboxGroup({
  options,
  value = [],
  onValueChange,
  disabled,
  label,
}: {
  options: { value: string; label: React.ReactNode; disabled?: boolean }[]
  value?: string[]
  onValueChange?: (value: string[]) => void
  disabled?: boolean
  label?: string
}): React.JSX.Element

export function PopoverContent({
  className,
  align = 'center',
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Content>): React.JSX.Element

export interface UIConfig {
    density: 'comfortable' | 'compact';
    direction: 'ltr' | 'rtl';
    locale: string;
}

export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
    density?: UIConfig['density'];
    direction?: UIConfig['direction'];
    locale?: string;
    accent?: string;
    radius?: number;
}

export interface TableView {
    visibility: Record<string, boolean>;
    order: string[];
    pinning: {
        left: string[];
        right: string[];
    };
    sizing: Record<string, number>;
}

export interface CellSpan {
    rowSpan: number;
    colSpan: number;
}

